html:
{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_path = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set dob = frappe.utils.formatdate(frappe.db.get_value("Applicant", doc.applicant_id, "date_of_birth")) -%}
{%- set father_name = frappe.db.get_value("Applicant", doc.applicant_id, "father_name") -%}
{%- set mother_name = frappe.db.get_value("Applicant", doc.applicant_id, "mother_name") -%}
{%- set issue_date = frappe.utils.formatdate(frappe.utils.nowdate()) -%}

{%- set _site = frappe.utils.get_url() -%}

{#- Logo Handling -#}
{%- set _logo_src = '' -%}
{%- if campus_logo_path -%}
    {%- set _lb64 = get_file_b64(campus_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (campus_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}
        {%- set _logo_src = _site ~ campus_logo_path -%}
    {%- endif -%}
{%- endif -%}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=794, initial-scale=1.0">
<title>Eligibility Result - {{ doc.applicant_id }}</title>
<style>
  @page {
    size: 210mm 297mm;
    margin: 8mm 6mm;
  }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  /* Reset Frappe wrapper elements */
  html, body, #page-body, .print-format-gutter, .print-format, .page-break, 
  .letter-head, .letter-head-content, form[data-doctype], .layout-main, 
  .layout-main-section, .frappe-card {
    margin: 0 !important; padding: 0 !important; border: none !important;
    background: transparent !important; width: auto !important; max-width: none !important;
  }

  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 8.5px;
    color: #000;
    background: #fff;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .pf-page {
    width: 100%;
    margin: 0;
    padding: 0;
    border: 2px solid #7b1a1a;
    background: #fff;
    display: block;
    overflow: hidden;
    page-break-after: always;
  }

  @media screen {
    body { background: #888; }
    .pf-page {
      width: 760px;
      max-width: 760px;
      margin: 20px auto !important;
      box-shadow: 0 6px 28px rgba(0, 0, 0, .45);
    }
  }

  /* Header */
  .hdr {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    background: #7b1a1a !important;
    border-bottom: 2px solid #5a0e0e;
  }
  .hdr-logo-td { width: 68px; padding: 9px 10px; text-align: center; vertical-align: middle; }
  .hdr-text-td { padding: 9px 8px; text-align: center; vertical-align: middle; }
  .logo-box {
    width: 50px; height: 50px; background: #fff !important; border-radius: 4px;
    display: inline-block; overflow: hidden;
  }
  .logo-box img { width: 44px; height: 44px; display: block; margin: 3px auto; object-fit: contain; }
  .hdr-inst { font-size: 11pt; font-weight: bold; text-transform: uppercase; color: #fff !important; }
  .hdr-sub { font-size: 6pt; letter-spacing: 1px; text-transform: uppercase; color: #ffcccc !important; margin-top: 2px; }

  /* Title Strip */
  .title-bar {
    width: 100%; text-align: center; padding: 8px 10px; background: #fff8f8 !important;
    border-bottom: 1px solid #7b1a1a;
  }
  .title-main { font-size: 10pt; font-weight: bold; color: #5a0000; }
  .title-sub { font-size: 7pt; color: #666; margin-top: 2px; }

  /* Section Header */
  .sec-hdr {
    background: #7b1a1a !important; color: #fff !important; font-weight: bold;
    padding: 5px 10px; font-size: 8pt; text-transform: uppercase;
    border: 1px solid #5a0e0e;
  }

  /* Form Table */
  .ft {
    width: 100%; border-collapse: collapse; table-layout: fixed; margin-bottom: -1px;
  }
  .ft td {
    border: 1px solid #7b1a1a; padding: 5px 8px; vertical-align: middle;
    font-size: 8.5px; line-height: 1.4; word-wrap: break-word;
  }
  .lbl { font-weight: bold; background-color: #f0f0f0 !important; color: #111 !important; width: 25%; }
  .sp { width: 5%; text-align: center; font-weight: bold; }
  .val { background-color: #fff !important; font-weight: bold; }

  /* Results Table */
  .res-tbl { width: 100%; border-collapse: collapse; margin-top: 10px; border: 1px solid #7b1a1a; }
  .res-tbl th { background: #ebebeb !important; font-weight: bold; padding: 6px 10px; border: 1px solid #7b1a1a; text-align: left; font-size: 8pt; }
  .res-tbl td { padding: 8px 10px; border: 1px solid #7b1a1a; font-size: 8.5px; }
  .score-cell { font-weight: bold; font-size: 10pt; color: #7b1a1a; }

  .disclaimer {
    margin: 15px; padding: 10px; background: #fff8f8 !important; border: 1px solid #7b1a1a;
    font-size: 7.5pt; line-height: 1.5; color: #333;
  }

  .footer {
    border-top: 1px solid #7b1a1a; padding: 10px 15px; display: flex; justify-content: space-between;
    font-size: 7pt; color: #555; background: #fff8f8 !important;
  }
</style>
</head>
<body>
<div class="pf-page">
  <table class="hdr" cellspacing="0" cellpadding="0">
    <tr>
      <td class="hdr-logo-td">
        <div class="logo-box">
          {% if _logo_src %}<img src="{{ _logo_src }}" alt="Logo">
          {% else %}<div style="line-height:50px; color:#7b1a1a; font-weight:bold; font-size:14px;">ILE</div>{% endif %}
        </div>
      </td>
      <td class="hdr-text-td">
        <div class="hdr-inst">{{ campus_display_name }}</div>
        <div class="hdr-sub">OFFICE OF ADMISSIONS &nbsp;&middot;&nbsp; ELIGIBILITY CELL</div>
      </td>
    </tr>
  </table>

  <div class="title-bar">
    <div class="title-main">Eligibility Result Mark Sheet</div>
    <div class="title-sub">Academic Year: {{ doc.academic_year or "—" }} &nbsp;&middot;&nbsp; Admission Cycle: {{ doc.admission_cycle or "—" }}</div>
  </div>

  <div class="sec-hdr">Candidate Details</div>
  <table class="ft">
    <tr>
      <td class="lbl">Candidate Name</td><td class="sp">:</td><td class="val">{{ doc.candidate_name or "—" }}</td>
      <td class="lbl">Application ID</td><td class="sp">:</td><td class="val">{{ doc.applicant_id or "—" }}</td>
    </tr>
    <tr>
      <td class="lbl">Date of Birth</td><td class="sp">:</td><td class="val">{{ dob or "—" }}</td>
      <td class="lbl">Gender</td><td class="sp">:</td><td class="val">{{ doc.gender or "—" }}</td>
    </tr>
    <tr>
      <td class="lbl">Father's Name</td><td class="sp">:</td><td class="val">{{ father_name or "—" }}</td>
      <td class="lbl">Mother's Name</td><td class="sp">:</td><td class="val">{{ mother_name or "—" }}</td>
    </tr>
  </table>

  <div class="sec-hdr" style="margin-top:10px;">Programme Details</div>
  <table class="ft">
    <tr>
      <td class="lbl">Programme</td><td class="sp">:</td><td class="val">{{ doc.program or "—" }}</td>
      <td class="lbl">Campus</td><td class="sp">:</td><td class="val">{{ doc.campus or "—" }}</td>
    </tr>
  </table>

  <div class="sec-hdr" style="margin-top:10px;">Assessment Result</div>
  <div style="padding: 0 15px;">
    <table class="res-tbl">
      <thead>
        <tr>
          <th>Assessment Component</th>
          <th>Maximum Marks</th>
          <th>Marks Obtained</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>Entrance Test Score</td>
          <td>100</td>
          <td class="score-cell">{{ doc.entrance_test_score or 0 }}</td>
        </tr>
        <tr>
          <td>Interview Assessment Score</td>
          <td>100</td>
          <td class="score-cell">{{ doc.interview_score or 0 }}</td>
        </tr>
        <tr style="background: #f9f9f9 !important;">
          <td colspan="2" style="text-align: right; font-weight: bold;">Result Status</td>
          <td style="font-weight: bold; font-size: 10pt; color: #1e6b1e;">{{ doc.result_status or "—" }}</td>
        </tr>
      </tbody>
    </table>
  </div>

  <div class="disclaimer">
    <strong>Important:</strong> This document is a system-generated mark sheet reflecting the eligibility assessment based on scores obtained. Final admission is subject to verification of original documents and fulfillment of all university criteria. Errors and omissions are excepted.
  </div>

  <div class="footer">
    <div>
      Ref: <strong>{{ doc.name }}</strong><br>
      Generated: <strong>{{ issue_date }}</strong><br>
      Source: {{ doc.source_type or "—" }}
    </div>
    <div style="text-align: right;">
      Authorized Signatory<br>
      <span style="font-size: 6pt; color: #888;">(Digitally Verified Document)</span>
    </div>
  </div>

  <div style="text-align: center; padding: 10px; color: #aaa; font-size: 10px;">
    *********
  </div>
</div>
</body>
</html>
